/**
 * F6 cell definitions (eval/runner/q1/cells/f6.ts) and the runner's F6 paths, keyless: the committed F6 manifest is
 * regenerated byte for byte, every cell is valid under definitionProblems, the arm policy identity keys retrievals
 * apart, F6 cells retrieve policy-major with each arm's own identity, and the dry-run campaign is capped and launches
 * the temporal graph's 0.31.2 bundle on every bootstrap call. Q1's manifest stays byte-identical (q1-cell.test.ts).
 */
import { afterAll, describe, expect, test } from 'bun:test';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { campaignManifest, findCell, runCell } from '../../eval/runner/q1/cell.ts';
import { Q1_CAMPAIGN_ID } from '../../eval/runner/shootout-cell.ts';
import { definitionProblems, estimateCell, loadManifest, manifestText, MANIFEST_PATH, policyKey, type ArmDefinition, type CellDefinition } from '../../eval/runner/q1/cells/definitions.ts';
import { ALL_ARMS, buildF6Manifest, F6_ARMS, F6_CAP_USD, F6_DRY_RUN_CAP_USD, F6_MANIFEST_PATH, f6ManifestText, peakReservationUsd } from '../../eval/runner/q1/cells/f6.ts';
import type { Corpus, MemoryQuestion } from '../../eval/runner/memory-qa/corpus.ts';
import type { ChatLike, ChatResult } from '../../eval/runner/memory-qa/qa-v2.ts';
import type { PublicQuestion, RetrievalPolicy } from '../../eval/runner/systems/types.ts';
import { FakeMemorySystem } from '../../eval/runner/systems/fake.ts';

const ROOT = resolve(import.meta.dir, '../..');
const tmp = mkdtempSync(join(tmpdir(), 'q1-f6-'));
afterAll(() => rmSync(tmp, { recursive: true, force: true }));
const kinds = new Set((JSON.parse(readFileSync(join(ROOT, 'eval/systems/kinds.json'), 'utf8')) as { kinds: Array<{ id: string }> }).kinds.map(k => k.id));
const m = buildF6Manifest();
const all = [...m.cells, ...m.smoke_cells];
const SONNET = 'anthropic:claude-sonnet-5-5';

describe('the F6 manifest', () => {
  test('f6-cells.json is the generated manifest (bun eval/runner/q1/cells/f6.ts), and Q1\'s stays as committed', () => {
    expect(readFileSync(F6_MANIFEST_PATH, 'utf8')).toBe(f6ManifestText());
    expect(readFileSync(MANIFEST_PATH, 'utf8')).toBe(manifestText());
    expect(m.preregistration).toBe('docs/benchmarks/2026-10-29-f6-current-master-preregistration.md');
  });
  test('every cell is valid, the estimate fits the $3,100 cap and the dry run fits $60', () => {
    for (const c of all) expect([c.id, definitionProblems(c, kinds)]).toEqual([c.id, []]);
    expect(m.cap_usd).toBe(F6_CAP_USD);
    expect(m.total_usd).toBeLessThanOrEqual(F6_CAP_USD);
    expect(m.smoke_cells.reduce((s, c) => s + c.estimate.usd, 0)).toBeLessThanOrEqual(F6_DRY_RUN_CAP_USD);
  });
  test('the scope: gbrain seven arms on S1, S2b, S2a, S3 and S4-slice, four on D8; the temporal graph 0.31.2 component arm; D8\'s comparison rows; nothing else rerun', () => {
    const ids = m.cells.map(c => c.id);
    expect(ids).toEqual(['s1.gbrain-defaults.f6-master', 's1.ext-temporal-graph.shipped-0.31', 's2b.gbrain-defaults.f6-master', 's2b.ext-temporal-graph.shipped-0.31',
      's2a.gbrain-defaults.f6-master', 's2a.ext-temporal-graph.shipped-0.31', 's3.gbrain-defaults.f6-master', 's3.ext-temporal-graph.shipped-0.31',
      'd8.gbrain-defaults.f6-master', 'd8.ext-memory-bank.recipe', 'd8.ext-graph-pipeline.recipe', 'd8.baseline-hybrid.baseline', 'd8.baseline-none.baseline', 's4-slice.gbrain-defaults.f6-master']);
    for (const c of m.cells.filter(c => c.system === 'gbrain-defaults')) expect(c.arms.map(a => a.id)).toEqual(c.set === 'D8' ? ['a', 'p', 'b', 'd'] : ALL_ARMS);
    for (const c of m.cells.filter(c => c.system !== 'gbrain-defaults')) expect(c.arms.map(a => [a.id, a.budget, a.retrieval])).toEqual([['component-b8000', 8000, undefined]]);
    expect(m.cells.find(c => c.set === 'S1' && c.system !== 'gbrain-defaults')!.shards).toBe(10);
    expect(m.cells.find(c => c.id === 's1.gbrain-defaults.f6-master')!.shards).toBe(10);
  });
  test('readers, judges and what F6 leaves out: three readers at 8,000, frontier judges only on S1 Sonnet answers of P and D, no repeats, replicates, sweep, own answers or probes', () => {
    for (const c of all) {
      expect(c.probes.conversations).toBe(0);
      for (const a of c.arms) {
        expect([a.mode, a.budget, a.readers, a.reader_replicates, a.judge_repeats]).toEqual(['packed', 8000, m.readers, {}, null]);
        const frontier = c.id === 's1.gbrain-defaults.f6-master' && (a.id === 'p' || a.id === 'd');
        expect(a.frontier).toEqual(frontier ? { judges: ['anthropic:claude-opus-5-5', 'openai:gpt-6.1-sol'], readers: [SONNET], sample: null } : null);
      }
    }
    expect([...m.readers].sort()).toEqual(['anthropic:claude-opus-5-5', 'anthropic:claude-sonnet-5-5', 'openai:gpt-6.1-sol']);
  });
  test('gbrain cells launch at the pin with F6 on and a recorded extraction cap; the temporal graph launches shipped-0.31 on up, down, snapshot and restore', () => {
    for (const c of all.filter(c => c.system === 'gbrain-defaults')) {
      expect(c.launch!.env).toMatchObject({ GBRAIN_F6: '1', GBRAIN_SHA: '0ccf2bdd4f42ed50be4cfb515eaa804ddb4b7049', GBRAIN_BUN_IMAGE: 'oven/bun:1.4.4-slim@sha256:1846adf22496bd711036aae8be147e57bdebbaea2e5264e3e0b5af1db187d9a4' });
      expect(Number(c.launch!.env.GBRAIN_F6_EXTRACT_CAP_USD)).toBeGreaterThanOrEqual(1);
      expect(c.estimate.lines).toHaveProperty('extraction');
    }
    for (const c of all.filter(c => c.system === 'ext-temporal-graph')) {
      expect(c.launch!.config).toBe('shipped-0.31');
      expect(c.snapshot_command).toContain('--config shipped-0.31');
      expect(c.restore_command).toContain('--config shipped-0.31');
    }
    expect(m.cells.find(c => c.id === 's1.gbrain-defaults.f6-master')!.launch!.env.GBRAIN_F6_EXTRACT_CAP_USD).toBe('5');
  });
  test('every lease holds its estimate per shard with margin plus twice the largest reservation the proxy can hold at once', () => {
    for (const c of m.cells) {
      const peak = peakReservationUsd(c);
      expect(peak.usd).toBeGreaterThan(0);
      expect(c.lease!.usd).toBeGreaterThanOrEqual(c.estimate.usd / c.shards * 1.25 + 2 * peak.usd - 0.01);
    }
    // A packed 8,000-token Opus read: (8,000 x 4.2 + 4,000 + 64) bytes at $4 in, plus the 2,048-token reader cap at $20 out.
    expect(peakReservationUsd(m.cells[0])).toEqual({ usd: Math.round(((8000 * 4.2 + 4000 + 64) * 4 + 2048 * 20) / 1e6 * 10_000) / 10_000, by: 'reader anthropic:claude-opus-5-5' });
  });
  test('the runner finds F6 cells by id, and the dry-run campaign is capped at $60 and admits the temporal graph\'s models', () => {
    expect(findCell('s3-smoke.gbrain-defaults.f6-master').arms.map(a => a.id)).toEqual(ALL_ARMS);
    const camp = campaignManifest(m, { smokeOnly: true });
    expect([camp.campaign_id, camp.cap_usd, camp.cells.map(c => c.id)]).toEqual(['q1-scoreboard-f6-current-master-dry-run', 60, ['s2b-ingest.gbrain-defaults.f6-master', 's2b-ingest.ext-temporal-graph.shipped-0.31', 's3-smoke.gbrain-defaults.f6-master']]);
    expect(Object.keys(camp.blocks ?? {})).toEqual(['F6-dry']);
    expect(camp.images['gbrain-defaults/base:1.4.4-slim']).toBe('sha256:1846adf22496bd711036aae8be147e57bdebbaea2e5264e3e0b5af1db187d9a4');
    expect(campaignManifest(loadManifest()).images).not.toHaveProperty('gbrain-defaults/base:1.4.4-slim');
    expect(camp.models).toEqual(expect.arrayContaining(['openai:gpt-6-luna', 'openai:text-embedding-3-small', 'anthropic:claude-haiku-5-5']));
    const tg = camp.cells.find(c => c.system === 'ext-temporal-graph')!;
    expect(tg.command).toContain('bootstrap.sh up --system ext-temporal-graph --config shipped-0.31');
    expect(tg.command).toContain('bootstrap.sh down --system ext-temporal-graph --config shipped-0.31');
    expect(camp.cells.find(c => c.id === 's3-smoke.gbrain-defaults.f6-master')!.command).toMatch(/^GBRAIN_BUN_IMAGE=oven\/bun:1\.4\.4-slim@sha256:[0-9a-f]{64} GBRAIN_F6=1 GBRAIN_F6_EXTRACT_CAP_USD=1 GBRAIN_SHA=0ccf2bdd/);
    // Setup builds the image up runs, so it gets the pin (and the temporal graph its own bundle) too.
    expect(camp.cells.find(c => c.id === 's3-smoke.gbrain-defaults.f6-master')!.setup_command).toBe('GBRAIN_BUN_IMAGE=oven/bun:1.4.4-slim@sha256:1846adf22496bd711036aae8be147e57bdebbaea2e5264e3e0b5af1db187d9a4 GBRAIN_SHA=0ccf2bdd4f42ed50be4cfb515eaa804ddb4b7049 bash eval/systems/bootstrap.sh setup --system gbrain-defaults --datasets locomo --conversations conv-44');
    expect(tg.setup_command).toBe('bash eval/systems/bootstrap.sh setup --system ext-temporal-graph --config shipped-0.31 --datasets beam-1m --conversations 1m-16');
    for (const c of campaignManifest(loadManifest()).cells) expect(c.setup_command).toMatch(/^bash eval\/systems\/bootstrap\.sh setup( --system [a-z0-9-]+)? --datasets /);
    for (const c of campaignManifest(m).cells.filter(c => c.system === 'gbrain-defaults')) expect(c.setup_command).toStartWith('GBRAIN_BUN_IMAGE=oven/bun:1.4.4-slim@sha256:1846adf22496bd711036aae8be147e57bdebbaea2e5264e3e0b5af1db187d9a4 GBRAIN_SHA=0ccf2bdd4f42ed50be4cfb515eaa804ddb4b7049 bash eval/systems/bootstrap.sh setup --system gbrain-defaults ');
    const counted = campaignManifest(m);
    expect([counted.campaign_id, counted.cap_usd, counted.cells.some(c => c.smoke)]).toEqual(['q1-scoreboard-f6-current-master', 3100, false]);
    for (const c of [camp, counted, campaignManifest(m, { sealed: { cap_usd: 3100 } })]) expect(c.campaign_id).toMatch(Q1_CAMPAIGN_ID);
  });
});

describe('the arm policy identity', () => {
  const arm = (id: string, extra: Partial<ArmDefinition> = {}): ArmDefinition => ({ id, cell_id: `x.${id}`, set: 'S3', arm: 'component', mode: 'packed', policy: 'fixed-evidence', budget: 8000, questions: null, readers: [SONNET], reader_replicates: {}, frontier: null, judge_repeats: null, label: id, ...extra });
  test('every F6 arm keys its own retrieval; equal identities share one; a Q1 arm keeps its mode as the key', () => {
    const keys = ALL_ARMS.map(id => policyKey(arm(id, { retrieval: F6_ARMS[id].retrieval })));
    expect(new Set(keys).size).toBe(7);
    for (const k of keys) expect(k).toMatch(/^fixed-evidence@(query|recall)-[0-9a-f]{12}$/);
    expect(policyKey(arm('x', { retrieval: structuredClone(F6_ARMS.p.retrieval) }))).toBe(keys[2]);
    expect(policyKey(arm('component-b8000'))).toBe('fixed-evidence');
    expect(policyKey(arm('w', { mode: 'own-answer', policy: null }))).toBeNull();
  });
  test('definitionProblems refuses an identity off an F6 gbrain stack, on a non-packed arm, with a bad op, a foreign argument or an incomplete overlay', () => {
    const base = m.cells.find(c => c.id === 's3.gbrain-defaults.f6-master')!;
    const withArm = (a: Partial<ArmDefinition>, c: Partial<CellDefinition> = {}) => definitionProblems({ ...base, ...c, arms: [{ ...base.arms[1], ...a }] }, kinds).join(' | ');
    expect(withArm({})).toBe('');
    expect(withArm({}, { launch: { env: {}, config: 'recipe' } })).toContain('GBRAIN_F6=1');
    expect(withArm({ mode: 'native-default', policy: 'vendor-default', budget: null })).toContain('only packed and retrieval-only arms carry a retrieval identity');
    expect(withArm({ retrieval: { ...F6_ARMS.a.retrieval, op: 'think' as 'query' } })).toContain('retrieval.op must be query or recall');
    expect(withArm({ retrieval: { ...F6_ARMS.a.retrieval, args: { budget_tokens: 5500 } } })).toContain('query takes no budget_tokens');
    expect(withArm({ retrieval: { ...F6_ARMS.a.retrieval, args: { token_budget: 0 } } })).toContain('token_budget must be a positive integer');
    const { ['search.fact_source_pages']: _, ...five } = F6_ARMS.a.retrieval.overlay;
    expect(withArm({ retrieval: { ...F6_ARMS.a.retrieval, overlay: five } })).toContain('must set exactly');
    expect(withArm({ retrieval: { ...F6_ARMS.a.retrieval, overlay: { ...F6_ARMS.a.retrieval.overlay, 'search.query_budget_unit': 'page' } } })).toContain('invalid value');
  });
});

describe('policy-major retrieval on F6 cells', () => {
  const raw = JSON.parse(readFileSync(join(ROOT, 'test/eval/fixtures/q1-cell/locomo-shaped.json'), 'utf8')) as { conversations: Corpus['conversations']; questions: MemoryQuestion[] };
  const corpus: Corpus = { benchmark: 'fixture', conversations: raw.conversations, questions: raw.questions, source: { name: 'LoCoMo-shaped fixture (invented)', files: [{ path: 'test/eval/fixtures/q1-cell/locomo-shaped.json', sha256: 'fixture' }], revision: 'repo', license: 'MIT' } };
  const reader: ChatLike = { async chat(): Promise<ChatResult> { return { text: 'The history does not say.', input_tokens: 10, output_tokens: 5, cached: false, finish: null, usage: null, response_model: null, attempt_errors: [] }; } };
  const judge: ChatLike = { async chat(): Promise<ChatResult> { return { text: 'no', input_tokens: 10, output_tokens: 1, cached: false, finish: null, usage: null, response_model: null, attempt_errors: [] }; } };
  class Recording extends FakeMemorySystem {
    calls: Array<{ ns: string; q: string; name: string; settings: unknown }> = [];
    async retrieve(ns: string, q: PublicQuestion, p: RetrievalPolicy) { this.calls.push({ ns, q: q.text, name: p.name, settings: p.settings }); return super.retrieve(ns, q, { ...p, settings: {} }); }
  }
  test('each conversation retrieves every question under one arm\'s identity before the next arm, and each arm reads its own retrieval', async () => {
    const id = 's3.gbrain-defaults.f6-master';
    const cell = m.cells.find(c => c.id === id)!;
    const base = { ...cell, split: 'dev' as const, selection: { kind: 'all' as const }, shards: 1, arms: cell.arms.filter(a => ['a', 'p', 'b'].includes(a.id)).map(a => ({ ...a, readers: [SONNET] })) };
    const def: CellDefinition = { ...base, estimate: estimateCell(base) };
    const system = new Recording();
    const out = join(tmp, 'policy-major');
    await runCell(def, { out, probeIntervalMs: 5, probeTimeoutMs: 2000 }, { corpus, system, reader, judge });
    const keys = def.arms.map(a => policyKey(a)!);
    // Besides the arms' retrievals, each conversation's readiness barrier reads once under Q1's fixed-evidence policy.
    const armCalls = system.calls.filter(c => c.name !== 'fake:fixed-evidence');
    const conversations = new Set(system.calls.map(c => c.ns));
    expect(system.calls.length - armCalls.length).toBe(conversations.size);
    expect(new Set(armCalls.map(c => c.name.split(':').slice(1).join(':')))).toEqual(new Set(keys));
    // Within a namespace (conversation), the policy changes exactly arms - 1 times: policy-major.
    for (const ns of conversations) {
      const seq = armCalls.filter(c => c.ns === ns).map(c => c.name);
      expect(seq.filter((n, i) => i > 0 && n !== seq[i - 1]).length).toBe(keys.length - 1);
    }
    expect(system.calls.find(c => c.name.endsWith(keys[2]))!.settings).toEqual({ op: 'recall', args: { budget_tokens: 5500 }, overlay: F6_ARMS.b.retrieval.overlay });
  });
});
